const start = {"screen": "opendt-overview"};
const week = {"from": "2022-10-06T22:00:00.000Z", "to": "2022-10-13T22:00:00.000Z"};
const status = "http://localhost:3001/api/status";
// the time a window shows: Week, the SURF week; Day or 6 h, the twin's last ones, within the week
const range = (window, twin) => {
  const hours = { day: 24, hours: 6 }[window];
  if (!hours) return week;
  const from = Math.max(new Date(twin).getTime() - hours * 3600000, new Date(week.from).getTime());
  return { from, to: from + hours * 3600000 };
};
// the view as the address has it, the twin's levers as the API has them
const view = { ...start, window: '${window}', period: '${period}', markers: '${markers}' };
context.panel.patchFormValue(view);
context.panel.setInitial({ ...context.panel.initial, ...view });
// a screen that starts on Day or 6 h shows the week until the twin's time is known
const address = context.grafana.locationService;
const { from = week.from, to = week.to } = address.getSearchObject();
if (view.window !== 'week' && from === week.from && to === week.to && context.panel.initial.twin_time) {
  address.partial(range(view.window, context.panel.initial.twin_time), true);
}
// Day and 6 h follow the twin: every 10 s, once its time passes the view's end, the view moves to its last
// hours; one timer per browser tab, though each screen and step mounts the control panel anew
globalThis.followTwin ??= setInterval(async () => {
  const address = context.grafana.locationService;
  const { 'var-window': shown = 'week', to } = address.getSearchObject();
  if (shown === 'week') return;
  const { twin_time } = await (await fetch(status)).json();
  const end = Number(to) || Date.parse(to); // the address has milliseconds or an ISO date
  if (Date.parse(twin_time) > end) address.partial(range(shown, twin_time), true);
}, 10000);
// while the twin starts, the API has no status yet: ask again in 5 s
if (!context.panel.initial?.twin_time) setTimeout(() => context.panel.initialRequest(), 5000);

