resetAction.code:
// Grafana's kiosk mode (no menus, no bars; Esc leaves it) in the browser's full screen, like a game
const on = !document.fullscreenElement;
on ? document.documentElement.requestFullscreen() : document.exitFullscreen();
context.grafana.locationService.partial({ kiosk: on || null });

options.styles:
.opendt-start { min-height: 70vh; width: 56%; margin: 0 auto; display: flex; flex-direction: column;
  justify-content: center; gap: 18px; }
.opendt-start .doing { color: #ccccdc; font-size: 17px; text-transform: uppercase; letter-spacing: 0.04em;
  white-space: nowrap; }
.opendt-start .bar { aspect-ratio: 24 / 1; background: #22252b; border-radius: 999px; overflow: hidden; }
.opendt-start .bar div { width: 0; height: 100%; border-radius: 999px; transition: width 0.2s linear;
  background: linear-gradient(90deg, #1f5f86, #338ec1 70%, #6cc0ee); box-shadow: 0 0 18px rgba(51, 142, 193, 0.55); }
.opendt-start .tip { position: fixed; bottom: 12%; left: 0; right: 0; text-align: center; color: #8e8e9e;
  font-size: 17px; white-space: nowrap; }

options.afterRender:
const progress = "http://localhost:3001/api/progress";
// the bar creeps toward the end of its step, so it never stands still; once the twin's first window is done, the
// page reloads to show the twin (the rows follow a variable read at load)
const state = (window.opendtStart ??= { step: 0, since: Date.now() });
const card = () => document.querySelector('.opendt-start');
const step = Number(card()?.dataset.step || 1);
if (step !== state.step) Object.assign(state, { step, since: Date.now() });
state.bar ??= setInterval(() => {
  const el = card();
  if (!el) return;
  const near = 1 - Math.exp(-(Date.now() - state.since) / 20000); // toward the end of the step, never at it
  el.querySelector('.bar div').style.width = (100 * (state.step - 1 + 0.9 * near)) / Number(el.dataset.steps) + '%';
}, 200);
state.ready ??= setInterval(async () => {
  try {
    const { data } = await (await fetch(progress)).json();
    if (!data.length) location.reload();
  } catch {} // the API is not up yet
}, 3000);

